// CSD_RATIONALE_BEGIN
// Root cause of attempt 73 regression (40.8% → 2.0%):
// Diagnostic confirms: avg 22.14 complete spans/example, avg span length 1.16 tokens.
// The evaluator extracts the LAST visible span as the answer; single-token spans
// like <<n>>, <<1>>, <<x>> are being closed immediately because IsCompletePrefix
// fires on any single identifier or constant, which are valid terminal expressions
// in the arithmetic grammar.
//
// Concrete rollout evidence:
//   "<<n1>> * (1 + p/100)" → span closes on n1 alone; rest is outside
//   "<<n>> - <<n>> + <<n>> ..." → repetition of single-variable spans
//   "<<1>> <<1>> <<1>> ..." → repetition of singleton number spans
//
// Fix: Add minimum expression length (minExprLen = 3) before closing.
//   Only close when |currentConstrainedOut| >= 3 OR ValidTokenCount == 0.
//   Single identifiers/constants are kept open and extended into full expressions.
// Additional: keep RenderedEndsWith for << detection (required); use
// AdaptiveConstrainedStep with validTokenGroups; CloseSpanWithinBudget for safety.
// Updated guidance emphasizes full operator-containing expressions.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span, RenderedEndsWith triggers → EnterObservedConstrainedSpan:
//     Sets currentConstrainedOut := []. parser.IsValidPrefix([]) holds by
//     method precondition `parser.IsValidPrefix([])`. ✓
//
//   Outside-span, RenderedEndsWith does not trigger:
//     insideConstrainedOut stays false; implication is vacuous. ✓
//
//   Inside-span, CloseConstrainedSpan path:
//     Sets insideConstrainedOut := false; implication vacuously true;
//     currentConstrainedOut := [] by helper postcondition. ✓
//
//   Inside-span, CloseSpanWithinBudget path:
//     Helper postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   Inside-span, AdaptiveConstrainedStep + AppendConstrainedToken path:
//     AdaptiveConstrainedStep returns a parser-valid token (or EOS) under hard
//     masking. AppendConstrainedToken's postcondition guarantees
//     parser.IsValidPrefix(currentConstrainedOut + [next]) when next is valid. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: |generatedPrefix| + 0 = |generatedPrefix|. ✓
//
//   UnconstrainedStep (non-EOS): steps += 1; generated gains 1 token;
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps. ✓
//
//   UnconstrainedStep (EOS): steps += 1; generated unchanged;
//     |generated| <= |generatedPrefix| + steps. ✓
//
//   CloseConstrainedSpan: steps += 1; generated gains at most 1 token (>>);
//     bound preserved. ✓
//
//   CloseSpanWithinBudget: closeBudget = maxSteps - steps; helper postcondition
//     gives |cg| <= |generated| + closeBudget = |generated| + (maxSteps - steps).
//     By inductive hypothesis |generated| <= |generatedPrefix| + steps, so
//     |cg| <= |generatedPrefix| + maxSteps. After steps := maxSteps: bound holds. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1 before append;
//     AppendConstrainedToken grows generated by exactly one token;
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math word problem step by step. For each intermediate computation and the final answer, write the COMPLETE arithmetic expression inside << >> delimiters. Each expression must include variables and operators, never a single variable or number alone. Examples: <<n1 * w1 + n2 * w2>>, <<int(n1 * frac) + n2>>, <<x * k * (12 // n)>>, <<n - n1*w1 - n2*w2 - int(n3*w3)>>. The final << >> must contain the full answer expression.");

var steps: nat := 0;
var minExprLen: nat := 3;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := eg;
        insideConstrainedOut := ei;
        currentConstrainedOut := ec;
      }
    }
  } else {
    // Inside a constrained span.
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    if parser.IsCompletePrefix(currentConstrainedOut) &&
       (|currentConstrainedOut| >= minExprLen || validCount == 0) {
      // Close: expression is complete and meaningful (long enough or terminal).
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 2 {
      // Near budget end: use CloseSpanWithinBudget to finish gracefully.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: advance one parser-valid token.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

